<?php

declare(strict_types=1);
// FMONITOR_TEST_DB: real transaction/rollback/authoritative composition checks.
require dirname(__DIR__).'/Support/AssignmentOrderOriginalIntegrityTestBootstrap.php';
require dirname(__DIR__).'/Support/AssignmentOrderOriginalIntegrityCommits.php';
require dirname(__DIR__).'/Support/AssignmentOrderOriginalIntegrityDatabase.php';
require dirname(__DIR__).'/Support/AssignmentOrderOriginalIntegrityPersistenceObserver.php';
require_once dirname(__DIR__,2).'/app/AssignmentOrderOriginal/MariaDbRuntimeRepository.php';
use FMonitor2\AssignmentOrderOriginal as O;
use FMonitor2\Tests\Support as S;

$f=null;
try{
    $f=new S\OriginalIntegrityDatabase();$db=$f->db;$repo=new O\AssignmentOrderOriginalMariaDbRepository($db,$f->prefix);
    $db->query('CREATE TEMPORARY TABLE integrity_order_baseline AS SELECT * FROM `'.$f->prefix.'fm2_assignment_orders`');
    $db->query('CREATE TEMPORARY TABLE integrity_member_baseline AS SELECT * FROM `'.$f->prefix.'fm2_order_installers`');
    $reset=static function()use($f,$db){$f->resetOriginals();$f->corrupt(function()use($f,$db){$db->query('DELETE FROM `'.$f->prefix.'fm2_order_installers`');$db->query('DELETE FROM `'.$f->prefix.'fm2_assignment_orders`');$db->query('INSERT INTO `'.$f->prefix.'fm2_assignment_orders` SELECT * FROM integrity_order_baseline');$db->query('INSERT INTO `'.$f->prefix.'fm2_order_installers` SELECT * FROM integrity_member_baseline');});};
    integrityCase('real-initial-commit-control',function()use($f,$repo,$reset){$reset();$process=[$f->rows('fm2_assignment_orders'),$f->rows('fm2_order_installers'),$f->rows('fm2_installation_cases'),$f->rows('fm2_process_tasks')];$r=$repo->commitAccepted(S\OriginalIntegrityCommits::accepted());assertSameValue(O\AssignmentOrderOriginalCommitStatus::COMMITTED,$r,'valid initial commits');$counts=[];foreach(array_slice(S\OriginalIntegrityDatabase::ORIGINAL_TABLES,0,5) as $table)$counts[]=count($f->rows($table));assertSameValue([1,1,1,1,1],$counts,'one root/revision/request/event/audit');assertSameValue($process,[$f->rows('fm2_assignment_orders'),$f->rows('fm2_order_installers'),$f->rows('fm2_installation_cases'),$f->rows('fm2_process_tasks')],'original commit never changes process/composition/opening');});
    integrityCase('real-correction-commit-preserves-history',function()use($f,$repo,$reset){$reset();$f->seedAccepted();$oldRevision=$f->rows('fm2_assignment_order_original_revisions')[0];$oldRequest=$f->rows('fm2_assignment_order_original_requests')[0];$oldRoot=$f->rows('fm2_assignment_order_original_roots')[0];$r=$repo->commitAccepted(S\OriginalIntegrityCommits::accepted(S\OriginalIntegrityCommits::correctionValues()));assertSameValue(O\AssignmentOrderOriginalCommitStatus::COMMITTED,$r,'valid correction commits');$revisions=$f->rows('fm2_assignment_order_original_revisions');$requests=$f->rows('fm2_assignment_order_original_requests');assertSameValue(2,count($revisions),'one appended revision');assertSameValue(true,in_array($oldRevision,$revisions,true),'old revision byte values retained');assertSameValue(true,in_array($oldRequest,$requests,true),'old request snapshot retained');$oldRoot['current_revision_id']='revision-0002';assertSameValue($oldRoot,$f->rows('fm2_assignment_order_original_roots')[0],'only current pointer advances');assertSameValue(2,count($f->rows('fm2_assignment_order_original_events')),'second event');assertSameValue(2,count($f->rows('fm2_assignment_order_original_audits')),'second audit');});
    foreach([false,true] as $correction)foreach(['changed-version','changed-engineer','missing-order','wrong-case','invalid-member'] as $kind)integrityCase('authoritative-composition-'.(int)$correction.'-'.$kind,function()use($f,$repo,$db,$reset,$correction,$kind){
        $reset();if($correction)$f->seedAccepted();$candidate=S\OriginalIntegrityCommits::accepted($correction?S\OriginalIntegrityCommits::correctionValues():[]);
        $f->corrupt(function()use($f,$db,$kind){switch($kind){case 'changed-version':$db->query('UPDATE `'.$f->prefix.'fm2_assignment_orders` SET version_no=2 WHERE id=81');break;case 'changed-engineer':$db->query('UPDATE `'.$f->prefix.'fm2_assignment_orders` SET control_engineer_user_id=32 WHERE id=81');break;case 'missing-order':$db->query('DELETE FROM `'.$f->prefix.'fm2_assignment_orders` WHERE id=81');break;case 'wrong-case':$db->query('UPDATE `'.$f->prefix.'fm2_assignment_orders` SET installation_case_id=9999 WHERE id=81');break;case 'invalid-member':$db->query('UPDATE `'.$f->prefix."fm2_order_installers` SET change_action='unknown' WHERE assignment_order_id=81 AND installer_tab_id=7001");break;}});
        $before=$f->facts();$catalog=$f->catalog();assertSameValue(O\AssignmentOrderOriginalCommitStatus::ROLLED_BACK,$repo->commitAccepted($candidate),'unresolvable authoritative drift is rollback, never invented semantic conflict');assertSameValue($before,$f->facts(),'zero original/process mutation on drift');assertSameValue($catalog,$f->catalog(),'no schema repair');
    });
    foreach(['revision-gap'=>['newRevisionNumber'=>7],'wrong-case'=>['installationCaseId'=>9999],'wrong-order'=>['assignmentOrderId'=>82,'compositionIdentity'=>'composition-82-v1'],'untrimmed-reason'=>['correctionReason'=>' Исправлено ']] as $name=>$changes)integrityCase('real-invalid-correction-'.$name,function()use($f,$repo,$reset,$changes){$reset();$f->seedAccepted();$before=$f->facts();assertSameValue(O\AssignmentOrderOriginalCommitStatus::ROLLED_BACK,$repo->commitAccepted(S\OriginalIntegrityCommits::accepted($changes+S\OriginalIntegrityCommits::correctionValues())),'invalid correction relation rolls back');assertSameValue($before,$f->facts(),'no partial root/revision/event/audit change');});
    integrityCase('real-direct-no-changes-conflict',function()use($f,$repo,$reset){$reset();$f->seedAccepted();$before=$f->facts();$candidate=S\OriginalIntegrityCommits::accepted(['documentDate'=>'2026-09-01']+S\OriginalIntegrityCommits::correctionValues());assertSameValue(O\AssignmentOrderOriginalCommitStatus::CONFLICT,$repo->commitAccepted($candidate),'direct no-op DTO defense is conflict; normal app detects it earlier');assertSameValue($before,$f->facts(),'no no-op revision/event');});
    integrityCase('real-stale-current-conflict',function()use($f,$repo,$reset){$reset();$f->seedAccepted();$f->seedAccepted(S\OriginalIntegrityCommits::correctionValues());$before=$f->facts();$candidate=S\OriginalIntegrityCommits::accepted(['requestId'=>'00000000-0000-4000-8000-000000000102','newRevisionId'=>'revision-0003','newRevisionNumber'=>3]+S\OriginalIntegrityCommits::correctionValues());assertSameValue(O\AssignmentOrderOriginalCommitStatus::CONFLICT,$repo->commitAccepted($candidate),'stale expected CAS conflict');assertSameValue($before,$f->facts(),'stale candidate creates no partial facts');});
    integrityCase('real-initial-unique-conflict',function()use($f,$repo,$reset){$reset();$f->seedAccepted();$before=$f->facts();$candidate=S\OriginalIntegrityCommits::accepted(['requestId'=>'00000000-0000-4000-8000-000000000999','rootOriginalId'=>'original-0099','newRevisionId'=>'revision-0099','documentDate'=>'2026-09-02']);assertSameValue(O\AssignmentOrderOriginalCommitStatus::CONFLICT,$repo->commitAccepted($candidate),'actual initial uniqueness winner conflict');assertSameValue($before,$f->facts(),'winner retained, no loser rows');});
    foreach([O\AssignmentOrderOriginalReason::INVALID_COMMAND,O\AssignmentOrderOriginalReason::STORAGE_FAILURE] as $reason)integrityCase('real-invalid-attempt-'.$reason->value,function()use($f,$repo,$reset,$reason){$reset();$before=$f->facts();assertSameValue(O\AssignmentOrderOriginalCommitStatus::ROLLED_BACK,$repo->commitAttempt(S\OriginalIntegrityCommits::attempt(['reason'=>$reason])),'invalid attempt cannot create terminal/audit');assertSameValue($before,$f->facts(),'invalid attempt zero mutation');});
    integrityCase('real-attempt-commit-and-collision',function()use($f,$repo,$reset){$reset();$a=S\OriginalIntegrityCommits::attempt();assertSameValue(O\AssignmentOrderOriginalCommitStatus::COMMITTED,$repo->commitAttempt($a),'terminal rejection and audit atomically committed');$before=$f->facts();assertSameValue(O\AssignmentOrderOriginalCommitStatus::CONFLICT,$repo->commitAttempt($a),'request-key collision has explicit conflict outcome');assertSameValue($before,$f->facts(),'duplicate attempt does not append or overwrite');});
    foreach(['before_write_begin','before_native_commit','after_native_commit'] as $point)foreach([false,true] as $attempt)integrityCase('native-confirmation-'.(int)$attempt.'-'.$point,function()use($f,$db,$reset,$point,$attempt){
        $reset();$before=$f->facts();$observer=new S\OriginalIntegrityPersistenceObserver(function($event)use($point){if($event->value===$point)throw new RuntimeException('synthetic acknowledgement boundary');});$repo=new O\AssignmentOrderOriginalMariaDbRepository($db,$f->prefix,null,$observer);
        $outcome=$attempt?$repo->commitAttempt(S\OriginalIntegrityCommits::attempt()):$repo->commitAccepted(S\OriginalIntegrityCommits::accepted());
        assertSameValue($point==='after_native_commit'?O\AssignmentOrderOriginalCommitStatus::OUTCOME_UNKNOWN:O\AssignmentOrderOriginalCommitStatus::ROLLED_BACK,$outcome,'confirmed rollback differs from lost commit acknowledgement');assertSameValue(1,count(array_filter($observer->events,fn($event)=>$event===$point)),'exact selected boundary observed once');
        if($point==='after_native_commit'){assertSameValue(1,count($f->rows('fm2_assignment_order_original_requests')),'committed request remains after acknowledgement loss');assertSameValue(1,count($f->rows('fm2_assignment_order_original_audits')),'committed audit remains');assertSameValue(0,count(array_filter($observer->events,fn($event)=>$event==='before_write_rollback')),'no pretend rollback after confirmed native commit');}
        else assertSameValue($before,$f->facts(),'before-commit failure rolls back all candidate rows');
        assertSameValue('0',(string)$db->query('SELECT @@in_transaction active')->fetch_assoc()['active'],'owned transaction not leaked');
    });
    integrityCase('rollback-observer-failure-still-releases-transaction',function()use($f,$db,$reset){$reset();$f->seedAccepted();$before=$f->facts();$observer=new S\OriginalIntegrityPersistenceObserver(function($event){if($event->value==='before_write_rollback')throw new RuntimeException('unconfirmed rollback wrapper');});$repo=new O\AssignmentOrderOriginalMariaDbRepository($db,$f->prefix,null,$observer);$candidate=S\OriginalIntegrityCommits::accepted(['requestId'=>'00000000-0000-4000-8000-000000000999','rootOriginalId'=>'original-0099','newRevisionId'=>'revision-0099','documentDate'=>'2026-09-02']);assertSameValue(O\AssignmentOrderOriginalCommitStatus::OUTCOME_UNKNOWN,$repo->commitAccepted($candidate),'unconfirmed rollback is not a proven conflict');assertSameValue('0',(string)$db->query('SELECT @@in_transaction active')->fetch_assoc()['active'],'native rollback still attempted');assertSameValue($before,$f->facts(),'winner/whole fact set retained');});
    integrityCase('native-query-false-control',function()use($f,$db,$reset){$reset();$before=$f->facts();$mode=(new mysqli_driver())->report_mode;mysqli_report(MYSQLI_REPORT_OFF);try{$missing=new O\AssignmentOrderOriginalMariaDbRepository($db,'missing_');assertSameValue(O\AssignmentOrderOriginalCommitStatus::ROLLED_BACK,$missing->commitAccepted(S\OriginalIntegrityCommits::accepted()),'native query false is an unconfirmed failure, not committed');}finally{mysqli_report($mode);}assertSameValue($before,$f->facts(),'query false never partially mutates own facts');});
    integrityCase('write-preserves-active-caller-transaction',function()use($f,$repo,$db,$reset){$reset();$before=$f->facts();$db->begin_transaction();try{$db->query('UPDATE `'.$f->prefix."fm2_installation_cases` SET process_state='caller-owned-uncommitted' WHERE id=9999");assertSameValue(O\AssignmentOrderOriginalCommitStatus::ROLLED_BACK,$repo->commitAccepted(S\OriginalIntegrityCommits::accepted()),'repository refuses to replace caller transaction');assertSameValue('1',(string)$db->query('SELECT @@in_transaction active')->fetch_assoc()['active'],'caller transaction remains live');}finally{$db->rollback();}assertSameValue($before,$f->facts(),'caller rollback still governs its marker');});
    integrityCase('real-positive-content-reference',function()use($f,$repo,$reset){$reset();$v=$f->seedAccepted();$before=$f->facts();$yes=$repo->hasCommittedContent($v['privateContentIdentity']);$no=$repo->hasCommittedContent('orphan-content-0099');assertSameValue([O\AssignmentOrderOriginalLookupStatus::FOUND,true,O\AssignmentOrderOriginalLookupStatus::FOUND,false],[$yes->status(),$yes->referenced(),$no->status(),$no->referenced()],'COUNT alias/shape cannot silently become false for referenced content');assertSameValue($before,$f->facts(),'reference reads have no repairs');});
}finally{if($f!==null)$f->close();}
integrityDone('ASSIGNMENT_ORDER_ORIGINAL_DATA_MARIADB_WRITES_OK');
